	private boolean recordDirectOperatorOutcome(TupleExpr node, InvocationAggregateObservation aggregate) {
		List<OperatorKey> keys = keysForRecord(node, null);
		if (keys.isEmpty()) {
			trace("record-skip-key", node, null, "");
			return false;
		}
		OperatorObservation observation = observationFor(node, aggregate);
		if (observation == null) {
			trace("record-skip-observation", node, keys.get(0), "");
			return false;
		}
		long epoch = nextFeedbackEpoch();
		for (OperatorKey key : keys) {
			learnedByOperator.computeIfAbsent(key, ignored -> new LearnedOperatorCounts())
					.add(observation, key.abstractedSignature(), epoch);
			trace("record", node, key, "actualRows=" + observation.actualRows() + ", plannedRows="
					+ observation.plannedRows() + ", actualWorkRows=" + observation.actualWorkRows()
					+ ", plannedWorkRows=" + observation.plannedWorkRows());
		}
		updateRuleSteeringSafety(node, observation, epoch);
		evictOldestIfNeeded();
		dirty = true;
		return true;
	}

	private boolean recordMultiplierOutcome(TupleExpr node, InvocationAggregateObservation aggregate) {
		OperatorKey key = multiplierKeyFor(node);
		OperatorObservation observation = observationFor(node, aggregate);
		if (key == null || observation == null) {
			trace("record-multiplier-skip", node, key, "");
			return false;
		}
		learnedMultipliers.computeIfAbsent(key, ignored -> new LearnedMultiplierCounts())
				.add(observation, nextFeedbackEpoch());
		evictOldestIfNeeded(learnedMultipliers);
		dirty = true;
		trace("record-multiplier", node, key, "actualRows=" + observation.actualRows()
				+ ", plannedRows=" + observation.plannedRows());
		return true;
	}

	private synchronized void recordPlanShadow(TupleExpr root, InvocationAggregateObservation aggregate) {
		if (root == null || isPlanFeedbackRecorded(root)) {
			return;
		}
		OperatorObservation observation = observationFor(root, aggregate);
		if (observation == null) {
			return;
		}
		OperatorKey key = planShadowKeyFor(root, false);
		if (key == null) {
			return;
		}
		long epoch = nextFeedbackEpoch();
		shadowByOperator.computeIfAbsent(key, ignored -> new ShadowOperatorCounts())
				.add(observation, epoch);
		recordPlanCandidateOutcome(root, observation, epoch);
		evictOldestIfNeeded(shadowByOperator);
		evictOldestIfNeeded(planCandidates);
		markPlanFeedbackRecorded(root);
		dirty = true;
		trace("record-plan-shadow", root, key, "actualRows=" + observation.actualRows()
				+ ", actualWorkRows=" + observation.actualWorkRows());
	}

	public synchronized void observePlanCandidate(TupleExpr tupleExpr, String ruleId, double estimatedRows,
			double estimatedWorkRows, int candidateRank, boolean accepted) {
		if (!adaptiveEvidenceAllowed()) {
			return;
		}
		OperatorKey key = planShadowKeyFor(tupleExpr);
		if (key == null || !isFiniteNonNegative(estimatedRows) || !isFiniteNonNegative(estimatedWorkRows)) {
			return;
		}
		planCandidates.computeIfAbsent(key, ignored -> new PlanCandidateCounts())
				.add(ruleId, estimatedRows, estimatedWorkRows, candidateRank, accepted, nextFeedbackEpoch());
		evictOldestIfNeeded(planCandidates);
		dirty = true;
	}

	public synchronized void observePlanCandidate(LeoPlanCandidate candidate, boolean accepted, String reason) {
		if (!adaptiveEvidenceAllowed()) {
			return;
		}
		if (candidate == null || candidate.tupleExpr() == null || !rollout().observationEnabled()) {
			return;
		}
		OperatorKey key = planCandidateKeyFor(candidate);
		if (key == null) {
			return;
		}
		planCandidates.computeIfAbsent(key, ignored -> new PlanCandidateCounts())
				.addCandidate(candidate, accepted, reason, nextFeedbackEpoch());
		evictOldestIfNeeded(planCandidates);
		dirty = true;
	}

	public synchronized Optional<LeoPlanRankingAdvice> planRankingAdvice(TupleExpr tupleExpr) {
		if (!adaptiveEvidenceAllowed()) {
			return Optional.empty();
		}
		if (shadowByOperator.isEmpty() && planCandidates.isEmpty()) {
			return Optional.empty();
		}
		OperatorKey key = planShadowKeyFor(tupleExpr);
		ShadowOperatorCounts actualCounts = key == null ? null : shadowByOperator.get(key);
		PlanCandidateCounts candidateCounts = key == null ? null : planCandidates.get(key);
		if (key == null || (actualCounts == null && candidateCounts == null)) {
			return Optional.empty();
		}
		String candidateId = candidateCounts == null ? "chosen" : candidateCounts.bestCandidateId();
		double expectedRows = actualCounts == null ? Double.NaN : actualCounts.meanRows();
		double expectedWorkRows = actualCounts == null ? candidateCounts.meanAcceptedWorkRows()
				: actualCounts.meanWorkRows();
		long evidence = (actualCounts == null ? 0L : actualCounts.sampleCount)
				+ (candidateCounts == null ? 0L : candidateCounts.sampleCount);
		double confidence = Math.min(0.80d, 0.25d + Math.log10(evidence + 1.0d) * 0.20d);
		String reason = candidateCounts == null
				? "shadow completed-plan feedback only"
				: "shadow top-k candidate feedback; accepted=" + candidateCounts.acceptedCount;
		return Optional.of(new LeoPlanRankingAdvice(key.fingerprint(), candidateId, expectedRows, expectedWorkRows,
				confidence, evidence, true, reason));
	}

	@Override
	public synchronized LeoPlanRanking rankPlanCandidates(List<LeoPlanCandidate> candidates) {
		if (candidates == null || candidates.isEmpty()) {
			return LeoPlanRanking.empty();
		}
		if (!adaptiveEvidenceAllowed()) {
			return LeoPlanRanking.byCost(candidates, "snapshot-only");
		}
		if (shadowByOperator.isEmpty() && planCandidates.isEmpty()) {
			return LeoPlanRanking.byCost(candidates, "lmdb-plan-ranking-no-evidence");
		}
		List<LeoPlanRanking.ScoredCandidate> scored = new ArrayList<>(candidates.size());
		for (LeoPlanCandidate candidate : candidates) {
			if (candidate == null) {
				continue;
			}
			double costScore = candidate.costScore();
			double learnedScore = costScore;
			double confidence = 0.0d;
			String source = "cost";
			TupleExpr tupleExpr = candidate.tupleExpr();
			OperatorKey key = planCandidateKeyFor(candidate);
			PlanCandidateCounts planCounts = key == null ? null : planCandidates.get(key);
			if (planCounts == null) {
				key = planCandidateKeyFor(tupleExpr, null, true);
				planCounts = key == null ? null : planCandidates.get(key);
			}
			if (planCounts != null) {
				learnedScore = planCounts.learnedScore(costScore);
				confidence = planCounts.confidence(feedbackEpoch);
				source = "plan-candidate:" + key;
			} else {
				ShadowOperatorCounts counts = key == null ? null : shadowByOperator.get(key);
				if (counts == null) {
					key = planShadowKeyFor(tupleExpr);
					counts = key == null ? null : shadowByOperator.get(key);
				}
				if (counts != null && counts.sampleCount > 0L) {
					learnedScore = counts.meanWorkRows();
					confidence = confidence(counts.sampleCount);
					source = "plan-shadow:" + key;
				}
			}
			scored.add(new LeoPlanRanking.ScoredCandidate(candidate, learnedScore, costScore, confidence, source));
		}
		if (scored.isEmpty()) {
			return LeoPlanRanking.empty();
		}
		scored.sort(java.util.Comparator.comparingDouble(LeoPlanRanking.ScoredCandidate::learnedScore)
				.thenComparingDouble(LeoPlanRanking.ScoredCandidate::costScore));
		String costWinner = scored.stream()
				.min(java.util.Comparator.comparingDouble(LeoPlanRanking.ScoredCandidate::costScore))
				.map(candidate -> candidate.candidate().candidateId())
				.orElse("");
		String learnedWinner = scored.getFirst().candidate().candidateId();
		boolean wouldChange = !Objects.equals(costWinner, learnedWinner);
		return new LeoPlanRanking(List.copyOf(scored), wouldChange,
				rollout().planRerankingEnabled() ? "lmdb-plan-ranking-active" : "lmdb-plan-ranking-shadow");
	}

	private boolean recordShadowOutcome(TupleExpr node, InvocationAggregateObservation aggregate) {
		OperatorKey key = shadowKeyFor(node);
		OperatorObservation observation = observationFor(node, aggregate);
		if (key == null || observation == null) {
			trace("record-shadow-skip", node, key, "");
			return false;
		}
		shadowByOperator.computeIfAbsent(key, ignored -> new ShadowOperatorCounts())
				.add(observation, nextFeedbackEpoch());
		evictOldestIfNeeded(shadowByOperator);
		dirty = true;
		trace("record-shadow", node, key, "actualRows=" + observation.actualRows());
		return true;
	}

	synchronized OperatorEstimate estimate(TupleExpr node, double leftRows, double rightRows, double baseRows,
			double baseWorkRows) {
		return estimate(node, leftRows, rightRows, baseRows, baseWorkRows, null, null);
	}

	synchronized OperatorEstimate estimate(TupleExpr node, double leftRows, double rightRows, double baseRows,
			double baseWorkRows, String executionMode) {
		return estimate(node, leftRows, rightRows, baseRows, baseWorkRows, executionMode, null);
	}

	synchronized OperatorEstimate estimate(TupleExpr node, double leftRows, double rightRows, double baseRows,
			double baseWorkRows, String executionMode, String planningContext) {
		if (!adaptiveEvidenceAllowed()) {
			return null;
		}
		OperatorEstimate frontierEstimate = frontierOperatorEstimate(node, baseRows, baseWorkRows);
		if (frontierEstimate != null) {
			return frontierEstimate;
		}
		if (learnedByOperator.isEmpty()) {
			trace("estimate-skip-empty", node, null, "");
			return null;
		}
		List<OperatorKey> keys = keysForEstimate(node, executionMode, planningContext);
		if (keys.isEmpty()) {
			trace("estimate-skip-key", node, null, "executionMode=" + executionMode);
			return null;
		}
		for (OperatorKey key : keys) {
			LearnedOperatorCounts counts = learnedByOperator.get(key);
			if (counts == null || counts.sampleCount <= 0L) {
				trace("estimate-miss", node, key, "executionMode=" + executionMode + ", size="
						+ learnedByOperator.size());
				continue;
			}
			if (key.generalized() && (counts.sampleCount < MIN_GENERALIZED_KEY_SAMPLES
					|| counts.distinctGeneralizedSignatures() < MIN_GENERALIZED_DISTINCT_SIGNATURES)) {
				trace("estimate-skip-generalized-undertrained", node, key, "executionMode=" + executionMode
						+ ", samples=" + counts.sampleCount
						+ ", distinct=" + counts.distinctGeneralizedSignatures());
				continue;
			}
			OperatorEstimate estimate = counts.estimate(node, leftRows, rightRows, baseRows, baseWorkRows,
					key.toString(), feedbackEpoch);
			if (estimate == null || !isFiniteNonNegative(estimate.rows())
					|| !isFiniteNonNegative(estimate.workRows())) {
				trace("estimate-invalid", node, key, "executionMode=" + executionMode);
				continue;
			}
			trace("estimate-hit", node, key, "executionMode=" + executionMode + ", rows=" + estimate.rows()
					+ ", workRows=" + estimate.workRows() + ", source=" + estimate.source());
			return estimate;
		}
		return null;
	}

	private OperatorEstimate frontierOperatorEstimate(TupleExpr node, double baseRows, double baseWorkRows) {
		if (node == null) {
			return null;
		}
		FrontierLearningKey key = FrontierLearningKey.parse(node.getStringMetricPlanned(FRONTIER_LEARNING_KEY));
		if (key == null) {
			return null;
		}
		FrontierLearningModel.DimensionEstimate rows = frontierLearning.estimate(
				key, FrontierCostDimension.OUTPUT_ROWS, baseRows);
		if (rows == null) {
			return null;
		}
		boolean databaseExact = "database_exact".equalsIgnoreCase(node.getStringMetricPlanned(FRONTIER_GUARANTEE));
		double correctedRows = databaseExact ? baseRows : rows.correctedValue();
		FrontierLearningModel.DimensionEstimate work = frontierLearning.estimate(
				key, FrontierCostDimension.SOURCE_ROWS_SCANNED, baseWorkRows);
		double correctedWork = work == null ? baseWorkRows : work.correctedValue();
		double confidence = posteriorConfidence(rows.posteriorPrecision());
		double rowQError = Math.max(1.0d, Math.exp(Math.abs(rows.posteriorLogMean())));
		double workQError = work == null ? 1.0d : Math.max(1.0d, Math.exp(Math.abs(work.posteriorLogMean())));
		double uncertaintyRows = Math.sqrt(Math.max(0.0d, rows.posteriorLogMeanVariance()))
				* Math.max(correctedRows, correctedWork);
		return new OperatorEstimate(correctedRows, Math.max(correctedRows, correctedWork),
				"frontier_hierarchical_nig", learningEvidenceCount(rows), confidence, confidence,
				key.externalForm(), rowQError, rowQError, workQError, workQError, uncertaintyRows);
	}

	private static long learningEvidenceCount(FrontierLearningModel.DimensionEstimate estimate) {
		return Math.max(1L, estimate.exactEvidenceCount() + estimate.familyEvidenceCount()
				+ estimate.legacyEvidenceCount());
	}

	private static double posteriorConfidence(double precision) {
		return isFiniteNonNegative(precision) ? Math.clamp(precision / (precision + 1.0d), 0.0d, 1.0d) : 0.0d;
	}

	synchronized OperatorEstimate multiplierEstimate(TupleExpr node, double baseRows, double baseWorkRows,
			String executionMode) {
		if (!adaptiveEvidenceAllowed() || !isFiniteNonNegative(baseRows) || !isFiniteNonNegative(baseWorkRows)) {
			return null;
		}
		OperatorKey key = multiplierKeyFor(node, executionMode);
		LearnedMultiplierCounts counts = key == null ? null : learnedMultipliers.get(key);
		if (counts == null) {
			OperatorKey legacyKey = legacyMultiplierKeyFor(node);
			if (legacyKey != null && !legacyKey.equals(key)) {
				key = legacyKey;
				counts = learnedMultipliers.get(key);
			}
		}
		if (counts == null || counts.sampleCount <= 0L) {
			return null;
		}
		double confidence = counts.confidenceModel.decayedConfidence(
				feedbackEpoch, CONFIDENCE_DECAY_HALF_LIFE_EPOCHS);
		double learnedRows = baseRows * counts.confidenceModel.rowCorrectionRatio();
		double learnedWorkRows = baseWorkRows * counts.confidenceModel.workCorrectionRatio();
		double rows = blend(baseRows, learnedRows, confidence);
		double workRows = Math.max(rows, blend(baseWorkRows, learnedWorkRows, confidence));
		if (!isFiniteNonNegative(rows) || !isFiniteNonNegative(workRows)) {
			return null;
		}
		double rowQErrorMax = Math.max(1.0d, counts.confidenceModel.rowQErrorMax());
		double workQErrorMax = Math.max(1.0d, counts.confidenceModel.workQErrorMax());
		double maximumQError = Math.min(MAX_UNCERTAINTY_Q_ERROR, Math.max(rowQErrorMax, workQErrorMax));
		double uncertaintyRows = maximumQError <= 1.0d
				? 0.0d
				: Math.max(rows, workRows) * (maximumQError - 1.0d) * Math.max(0.05d, 1.0d - confidence);
		if (!isFiniteNonNegative(uncertaintyRows)) {
			uncertaintyRows = 0.0d;
		}
		return new OperatorEstimate(
				rows,
				workRows,
				LEARNED_MULTIPLIER,
				counts.sampleCount,
				confidence,
				confidence,
				key.toString(),
				counts.confidenceModel.rowQErrorMean(),
				rowQErrorMax,
				counts.confidenceModel.workQErrorMean(),
				workQErrorMax,
				uncertaintyRows);
	}

	/**
	 * Monotonic version for planning artifacts that consume learned operator evidence. Lifecycle registry admissions
	 * are deliberately excluded: compiling a plan may register monitoring envelopes, but that bookkeeping supplies no
	 * new execution evidence and must not invalidate the plan being compiled. Every completed runtime observation and
	 * every actionable lifecycle transition advances {@link #feedbackEpoch} before it can affect a subsequent plan.
	 */
	synchronized long planningRevision() {
		return feedbackEpoch;
	}

	synchronized PlanLifecycleStore.Decision planLifecycleDecision(LogicalLearningKey logicalKey,
			PhysicalResidualKey physicalKey, LearningApplicability applicability,
			PlanLifecycleStore.ObjectiveEnvelope envelope) {
		Objects.requireNonNull(logicalKey, "logical key");
		Objects.requireNonNull(physicalKey, "physical key");
		Objects.requireNonNull(applicability, "learning applicability");
		Objects.requireNonNull(envelope, "objective envelope");
		if (!adaptiveEvidenceAllowed()) {
			return new PlanLifecycleStore.Decision(PlanLifecycleStore.State.MONITORING, true, false,
					envelope.point(), envelope, "", Double.NaN, Double.POSITIVE_INFINITY, "snapshot-only");
		}
		long priorRevision = planLifecycle.revision();
		PlanLifecycleStore.Decision decision = planLifecycle.decision(logicalKey, physicalKey, applicability,
				envelope, rollout().planLifecycleEnforced());
		if (planLifecycle.revision() != priorRevision) {
			dirty = true;
		}
		return decision;
	}

	boolean planLifecycleEnforced() {
		return rollout().planLifecycleEnforced();
	}

	public synchronized LeoMemoFeedback memoFeedback(TupleExpr tupleExpr, BindingUniverse universe,
			BindingShape bindingShape) {
		if (!adaptiveEvidenceAllowed()) {
			return LeoMemoFeedback.empty();
		}
		if (tupleExpr == null) {
			return LeoMemoFeedback.empty();
		}
		if (!supportsOperatorFeedback(tupleExpr)) {
			return planRankingAdvice(tupleExpr)
					.map(advice -> {
						List<LeoRuleHint> hints = planRankingHints(tupleExpr, advice);
						if (hints.stream().anyMatch(hint -> hint.priorityDelta() != 0)) {
							tupleExpr.setStringMetricPlanned(LEO_RULE_STEERING_APPLIED, "true");
						}
						return LeoMemoFeedback.of(List.of(), hints);
					})
					.orElseGet(LeoMemoFeedback::empty);
		}
		double baseRows = memoBaseRows(tupleExpr);
		double baseWorkRows = memoBaseWorkRows(tupleExpr, baseRows);
		String planningContext = bindingShapeContext(universe, bindingShape, tupleExpr);
		if (!planningContext.isBlank()) {
			tupleExpr.setStringMetricPlanned(LEO_BINDING_SHAPE_KEY, planningContext);
		}
		String executionMode = physicalExecutionMode(tupleExpr, null);
		if (executionMode != null && !executionMode.isBlank()) {
			tupleExpr.setStringMetricPlanned(LEO_PHYSICAL_IMPLEMENTATION, executionMode);
		}
		OperatorEstimate estimate = estimate(tupleExpr, Double.NaN, Double.NaN, baseRows, baseWorkRows,
				executionMode, planningContext);
		if (estimate == null) {
			return planRankingAdvice(tupleExpr)
					.map(advice -> LeoMemoFeedback.of(List.of(), planRankingHints(tupleExpr, advice)))
					.orElseGet(LeoMemoFeedback::empty);
		}
		LeoEvidence evidence = new LeoEvidence(estimate.rows(), estimate.workRows(), estimate.correctionConfidence(),
				estimate.evidenceCount(), estimate.rowQErrorMean(), estimate.rowQErrorMax(),
				estimate.workQErrorMean(), estimate.workQErrorMax(), estimate.uncertaintyRows(),
				estimate.source(), LeoEvidence.Kind.SCALAR_OPERATOR_FEEDBACK, false);
		List<LeoRuleHint> hints = new ArrayList<>(ruleHints(tupleExpr, baseRows, baseWorkRows, estimate));
		planRankingAdvice(tupleExpr).ifPresent(advice -> hints.addAll(planRankingHints(tupleExpr, advice)));
		if (hints.stream().anyMatch(hint -> hint.priorityDelta() != 0)) {
			tupleExpr.setStringMetricPlanned(LEO_RULE_STEERING_APPLIED, "true");
		}
		return LeoMemoFeedback.of(List.of(evidence), hints);
	}

	public synchronized Optional<LeoEvidence> evidence(LeoSurfaceKey key) {
		return adaptiveEvidenceAllowed() ? fanoutEvidence(key) : Optional.empty();
	}

	synchronized void recordFanout(long predicateId, LmdbLeoSurfaceStats.BoundPosition position, long valueId,
			long fanout, long epoch) {
		recordFanout(predicateId, position, valueId, LmdbLeoSurfaceStats.ANY_CONTEXT_ID, fanout, epoch);
	}

	synchronized void recordFanout(long predicateId, LmdbLeoSurfaceStats.BoundPosition position, long valueId,
			long contextId, long fanout, long epoch) {
		if (!adaptiveEvidenceAllowed()) {
			return;
		}
		if (leoSurfaceStats.recordFanout(predicateId, position, valueId, contextId, fanout, epoch)) {
			surfaceDirty = true;
		}
	}

	synchronized Optional<LeoEvidence> estimateFanout(long predicateId, LmdbLeoSurfaceStats.BoundPosition position,
			long valueId, long contextId) {
		if (!adaptiveEvidenceAllowed()) {
			return Optional.empty();
		}
		return leoSurfaceStats.estimateFanout(predicateId, position, valueId, contextId)
				.or(() -> leoSurfaceStats.bucketEstimate(predicateId, position, valueId, contextId))
				.or(() -> leoSurfaceStats.predicateEstimate(predicateId, position, valueId, contextId))
				.map(LmdbOperatorFeedbackStats::fanoutEvidence);
	}

	private static double memoBaseRows(TupleExpr tupleExpr) {
		return finiteOr(tupleExpr.getCostFeedbackExpectedRows(), tupleExpr.getResultSizeEstimate());
	}

	private static double memoBaseWorkRows(TupleExpr tupleExpr, double baseRows) {
		double workRows = finiteOr(tupleExpr.getCostFeedbackExpectedWorkRows(),
				finiteOr(tupleExpr.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS),
						tupleExpr.getCostEstimate()));
		return isFiniteNonNegative(workRows) ? workRows : baseRows;
	}

	private Optional<LeoEvidence> fanoutEvidence(LeoSurfaceKey key) {
		if (key == null || !"fanout".equals(key.operatorKind())) {
			return Optional.empty();
		}
		Optional<Long> predicateId = parseLong(key.predicateId());
		Optional<Long> valueId = parseLong(key.valueId());
		Optional<Long> contextId = key.accessPathId().isBlank()
				? Optional.of(LmdbLeoSurfaceStats.ANY_CONTEXT_ID)
				: parseLong(key.accessPathId());
		Optional<LmdbLeoSurfaceStats.BoundPosition> position = boundPosition(key.boundPosition());
		if (predicateId.isEmpty() || valueId.isEmpty() || contextId.isEmpty() || position.isEmpty()) {
			return Optional.empty();
		}
		return estimateFanout(predicateId.get(), position.get(), valueId.get(), contextId.get());
	}

	private static LeoEvidence fanoutEvidence(LmdbLeoSurfaceStats.FanoutEstimate estimate) {
		return LeoEvidence.persistedFanoutHistogram(estimate.rows(), estimate.rows(), estimate.confidence(),
				estimate.evidenceCount(), estimate.source());
	}

	private static Optional<Long> parseLong(String value) {
		try {
			return Optional.of(Long.parseLong(value));
		} catch (RuntimeException e) {
			return Optional.empty();
		}
	}

	private static Optional<LmdbLeoSurfaceStats.BoundPosition> boundPosition(String value) {
		if (value == null) {
			return Optional.empty();
		}
		return switch (value) {
		case "subject" -> Optional.of(LmdbLeoSurfaceStats.BoundPosition.SUBJECT);
		case "object" -> Optional.of(LmdbLeoSurfaceStats.BoundPosition.OBJECT);
		default -> Optional.empty();
		};
	}

	private static void trace(String event, TupleExpr node, OperatorKey key, String details) {
		if (!Boolean.getBoolean(ESTIMATE_TRACE_PROPERTY)) {
			return;
		}
		StringBuilder message = new StringBuilder(256);
		message.append("[lmdb-operator-feedback-trace] event=")
				.append(event)
				.append(" node=")
				.append(node == null ? "<null>" : node.getClass().getSimpleName());
		if (key != null) {
			message.append(" key=").append(key);
		}
		if (details != null && !details.isEmpty()) {
			message.append(" details={").append(details).append('}');
		}
		System.err.println(message);
	}

	private static String completionDetails(TupleExpr node, boolean completedRoot) {
		if (node == null) {
			return "completedRoot=" + completedRoot;
		}
		return "completedRoot=" + completedRoot
				+ ", tracking=" + node.isCostFeedbackTrackingEnabled()
				+ ", feedbackCompleted=" + node.isCostFeedbackCompletedActual()
				+ ", feedbackActualRows=" + node.getCostFeedbackActualRows()
				+ ", resultSizeActual=" + node.getResultSizeActual()
				+ ", outputRowsActual=" + longMetric(node, TelemetryMetricNames.OUTPUT_ROWS_ACTUAL)
				+ ", closeCount=" + node.getLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL)
				+ ", hasNextCalls=" + node.getHasNextCallCountActual()
				+ ", hasNextTrueCalls=" + node.getHasNextTrueCountActual()
				+ ", plannedRepeatedInvocations=" + node.getDoubleMetricPlanned(PLANNED_REPEATED_INVOCATIONS)
				+ ", plannedOperatorRepeatedInvocations="
				+ node.getDoubleMetricPlanned(PLANNED_OPERATOR_REPEATED_INVOCATIONS)
				+ ", feedbackCloseCount=" + node.getCostFeedbackCloseCountActual();
	}

	public synchronized void persistIfDirty() {
		if (!adaptiveEvidenceAllowed()) {
			return;
		}
		if (!dirty && !surfaceDirty) {
			return;
		}
		SketchSnapshotIdentity snapshotIdentity = currentSnapshotIdentity();
		if (snapshotIdentity == null) {
			return;
		}
		if (dirty && persistOperatorFeedback(snapshotIdentity)) {
			dirty = false;
		}
		if (surfaceDirty && persistLeoSurfaces(snapshotIdentity)) {
			surfaceDirty = false;
		}
	}

	private boolean persistOperatorFeedback(SketchSnapshotIdentity snapshotIdentity) {
		Path tempPath = sidecarPath.resolveSibling(sidecarPath.getFileName().toString() + ".tmp");
		try (DataOutputStream out = new DataOutputStream(Files.newOutputStream(tempPath))) {
			out.writeInt(PERSIST_VERSION);
			snapshotIdentity.writeTo(out);
			// The sketch identity only changes when the async synopsis rebuild publishes. The journal sequence closes
			// the intervening statement-commit window without treating metadata-only LMDB commits as data mutations.
			out.writeLong(appliedStatementMutationStamp);
			out.writeLong(feedbackEpoch);
			out.writeLong(ruleSteeringCooldownUntilEpoch);
			out.writeInt(ruleSteeringBadMisses);
			out.writeInt(learnedByOperator.size());
			for (var entry : learnedByOperator.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
			out.writeInt(learnedMultipliers.size());
			for (var entry : learnedMultipliers.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
			out.writeInt(shadowByOperator.size());
			for (var entry : shadowByOperator.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
			out.writeInt(planCandidates.size());
			for (var entry : planCandidates.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
			out.writeInt(semiAntiBySurface.size());
			for (var entry : semiAntiBySurface.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
			frontierLearning.writeTo(out);
			int exactFactCount = 0;
			for (ExactCardinalityCell cell : exactCardinalityFacts.values()) {
				exactFactCount += cell.hasFact() ? 1 : 0;
			}
			out.writeInt(exactFactCount);
			for (var entry : exactCardinalityFacts.entrySet()) {
				ExactCardinalityCell cell = entry.getValue();
				if (cell.hasFact()) {
					out.writeUTF(entry.getKey());
					out.writeDouble(cell.rows);
					out.writeLong(cell.statementMutationStamp);
				}
			}
			planLifecycle.writeTo(out);
			out.writeInt(typedSemiAntiDistinct.size());
			for (var entry : typedSemiAntiDistinct.entrySet()) {
				entry.getKey().writeTo(out);
				entry.getValue().writeTo(out);
			}
		} catch (IOException e) {
			deleteIfExists(tempPath);
			return false;
		}

		try {
			Files.move(tempPath, sidecarPath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			return true;
		} catch (IOException atomicMoveFailure) {
			try {
				Files.move(tempPath, sidecarPath, StandardCopyOption.REPLACE_EXISTING);
				return true;
			} catch (IOException moveFailure) {
				deleteIfExists(tempPath);
				return false;
			}
		}
	}

	private boolean persistLeoSurfaces(SketchSnapshotIdentity snapshotIdentity) {
		try {
			leoFeedbackStore.persist(snapshotIdentity.token(), appliedStatementMutationStamp, leoSurfaceStats);
			return true;
		} catch (IOException e) {
			return false;
		}
	}

	private LmdbLeoSurfaceStats loadLeoSurfaceStats() {
		SketchSnapshotIdentity currentIdentity = currentSnapshotIdentity();
		if (currentIdentity == null) {
			return new LmdbLeoSurfaceStats(leoFeedbackConfig);
		}
		try {
			return leoFeedbackStore.load(currentIdentity.token(), appliedStatementMutationStamp);
		} catch (IOException | RuntimeException e) {
			return new LmdbLeoSurfaceStats(leoFeedbackConfig);
		}
	}

	private void loadIfPresent() {
		if (!Files.isRegularFile(sidecarPath)) {
			return;
		}
		SketchSnapshotIdentity currentIdentity = currentSnapshotIdentity();
		if (currentIdentity == null) {
			return;
		}

		Map<OperatorKey, LearnedOperatorCounts> loaded = new LinkedHashMap<>();
		Map<OperatorKey, LearnedMultiplierCounts> loadedMultipliers = new LinkedHashMap<>();
		Map<OperatorKey, ShadowOperatorCounts> loadedShadow = new LinkedHashMap<>();
		Map<OperatorKey, PlanCandidateCounts> loadedPlanCandidates = new LinkedHashMap<>();
		Map<SemiAntiSurfaceKey, SemiAntiCounts> loadedSemiAnti = new LinkedHashMap<>();
		Map<TypedSemiAntiDistinctKey, TypedSemiAntiDistinctCounts> loadedTypedSemiAntiDistinct = new LinkedHashMap<>();
		Map<String, ExactCardinalityCell> loadedExactFacts = new LinkedHashMap<>();
		FrontierLearningModel loadedFrontierLearning = new FrontierLearningModel();
		PlanLifecycleStore loadedPlanLifecycle = new PlanLifecycleStore(MAX_ENTRIES);
		long loadedEpoch = 0L;
		long loadedSteeringCooldownUntilEpoch = 0L;
		int loadedSteeringBadMisses = 0;
		try (DataInputStream in = new DataInputStream(Files.newInputStream(sidecarPath))) {
			int version = in.readInt();
			if (version != PERSIST_VERSION) {
				return;
			}
			SketchSnapshotIdentity persistedIdentity = SketchSnapshotIdentity.readFrom(in);
			if (!persistedIdentity.equals(currentIdentity)) {
				return;
			}
			long persistedStatementMutationStamp = in.readLong();
			if (sidecarDataStampCheckEnabled()
					&& persistedStatementMutationStamp != appliedStatementMutationStamp) {
				return;
			}
			if (version >= 10) {
				loadedEpoch = Math.max(0L, in.readLong());
			}
			if (version >= 11) {
				loadedSteeringCooldownUntilEpoch = Math.max(0L, in.readLong());
				loadedSteeringBadMisses = Math.max(0, in.readInt());
			}
			int entries = in.readInt();
			if (entries < 0 || entries > MAX_ENTRIES * 4) {
				return;
			}
			for (int i = 0; i < entries; i++) {
				OperatorKey key = OperatorKey.readFrom(in);
				LearnedOperatorCounts counts = LearnedOperatorCounts.readFrom(in, version);
				if (counts.sampleCount > 0L) {
					loaded.put(key, counts);
				}
			}
			if (version >= 10) {
				readMultiplierEntries(in, loadedMultipliers);
				readShadowEntries(in, loadedShadow);
			}
			if (version >= 11) {
				readPlanCandidateEntries(in, loadedPlanCandidates);
			}
			if (version >= SEMI_ANTI_PERSIST_VERSION) {
				readSemiAntiEntries(in, loadedSemiAnti, version);
			}
			/*
			 * Version-15 files DO carry a serialized frontier model, but it predates the topology-suffixed join keys
			 * and the recording-coherence guards — its exact-key corrections can contain drift poison that the new keys
			 * would only partially orphan (leaving e.g. crushed leaf-scan costs live while the join corrections that
			 * compensated them go cold). Version-16 models are discarded for the same reason a generation later: they
			 * pair cumulative actuals with per-invocation predictions for re-invoked operators (and pre-date the
			 * group-canonical OUTPUT_ROWS families), so partially retaining them would leave e.g. a 4.9x VALUES-anchor
			 * inflation live while the commensurate observations that should replace it start from zero. Discard and
			 * fall back to the legacy prior import; the model relearns coherently under the new recording rules.
			 * Versions 18 and 19 have typed keys, but their logical posterior stores raw-relative residuals. Version 20
			 * changes that payload to absolute logical truth, so older typed models, exact facts, and lifecycle state
			 * are consumed for deterministic validation and then quarantined rather than silently changing meaning.
			 */
			if (version >= LOGICAL_PHYSICAL_PERSIST_VERSION) {
				FrontierLearningModel persistedFrontierLearning = FrontierLearningModel.readFrom(
						in, version >= LEO_PLUS_PERSIST_VERSION);
				if (version >= ABSOLUTE_LOGICAL_PERSIST_VERSION) {
					loadedFrontierLearning = persistedFrontierLearning;
				}
				int factCount = in.readInt();
				if (factCount < 0 || factCount > MAX_ENTRIES * 4) {
					return;
				}
				for (int i = 0; i < factCount; i++) {
					String factKey = in.readUTF();
					double rows = in.readDouble();
					long statementMutationStamp = in.readLong();
					if (version >= ABSOLUTE_LOGICAL_PERSIST_VERSION && isFiniteNonNegative(rows)) {
						loadedExactFacts.put(factKey, new ExactCardinalityCell(rows, statementMutationStamp));
					}
				}
				if (version >= PLAN_LIFECYCLE_PERSIST_VERSION) {
					PlanLifecycleStore persistedPlanLifecycle = PlanLifecycleStore.readFrom(in, MAX_ENTRIES);
					if (version >= ABSOLUTE_LOGICAL_PERSIST_VERSION) {
						loadedPlanLifecycle = persistedPlanLifecycle;
					}
				}
				if (version >= PERSIST_VERSION) {
					readTypedSemiAntiDistinctEntries(in, loadedTypedSemiAntiDistinct);
				}
			} else if (version == INVOCATION_AGGREGATE_PERSIST_VERSION) {
				/*
				 * V17 stored topology-keyed cardinality and physical corrections. Consume it only so the file is
				 * validated deterministically; neither those corrections nor its topology-keyed facts are safe to
				 * reinterpret as canonical logical truth.
				 */
				FrontierLearningModel.discardLegacyFrom(in);
				int quarantinedFactCount = in.readInt();
				if (quarantinedFactCount < 0 || quarantinedFactCount > MAX_ENTRIES * 4) {
					return;
				}
				for (int i = 0; i < quarantinedFactCount; i++) {
					in.readUTF();
					in.readDouble();
					in.readLong();
				}
			} else {
				importLegacyFrontierPriors(loadedFrontierLearning, loaded, loadedMultipliers);
			}
		} catch (IOException | RuntimeException e) {
			return;
		}

		synchronized (this) {
			learnedByOperator.clear();
			learnedByOperator.putAll(loaded);
			learnedMultipliers.clear();
			learnedMultipliers.putAll(loadedMultipliers);
			shadowByOperator.clear();
			shadowByOperator.putAll(loadedShadow);
			planCandidates.clear();
			planCandidates.putAll(loadedPlanCandidates);
			semiAntiBySurface.clear();
			semiAntiBySurface.putAll(loadedSemiAnti);
			typedSemiAntiDistinct.clear();
			typedSemiAntiDistinct.putAll(loadedTypedSemiAntiDistinct);
			/* Compatibility surfaces persist, but event-origin authority is deliberately re-earned after restart. */
			frontierOriginSemiAntiSurfaces.clear();
			exactCardinalityFacts.clear();
			exactCardinalityFacts.putAll(loadedExactFacts);
			frontierLearning = loadedFrontierLearning;
			planLifecycle = loadedPlanLifecycle;
			nullModeKeyCache.clear();
			planningLeoKeyCache.clear();
			feedbackEpoch = Math.max(feedbackEpoch, loadedEpoch);
			ruleSteeringCooldownUntilEpoch = Math.max(ruleSteeringCooldownUntilEpoch,
					loadedSteeringCooldownUntilEpoch);
			ruleSteeringBadMisses = loadedSteeringBadMisses;
			evictOldestIfNeeded();
			evictOldestIfNeeded(learnedMultipliers);
			evictOldestIfNeeded(shadowByOperator);
			evictOldestIfNeeded(planCandidates);
			evictOldestIfNeeded(semiAntiBySurface);
			evictOldestIfNeeded(typedSemiAntiDistinct);
			dirty = false;
		}
	}

	private OperatorObservation observationFor(TupleExpr node, InvocationAggregateObservation aggregate) {
		if (aggregate == null) {
			aggregate = EvaluationStatistics.legacyInvocationAggregateObservation(node, true);
		}
		if (aggregate == null) {
			return null;
		}
		double actualRows = aggregate.actualRowsSum();
		if (!isFiniteNonNegative(actualRows)) {
			return null;
		}
		double plannedRows = aggregate.rawPredictedRowsSum();
		if (!isFiniteNonNegative(plannedRows)) {
			plannedRows = finiteOr(node.getCostFeedbackExpectedRows(),
					finiteOr(node.getResultSizeEstimate(), actualRows));
		}
		double plannedWorkRows = aggregate.rawPredictedWorkSum().workRows();
		if (!isFiniteNonNegative(plannedWorkRows)) {
			plannedWorkRows = finiteOr(node.getCostFeedbackExpectedWorkRows(),
					finiteOr(node.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS), plannedRows));
		}
		double leftRows = leftRows(node);
		double rightRows = rightRows(node);
		double leftRowsWithMatch = finiteOr(node.getCostFeedbackLeftRowsWithMatchActual(),
				longMetric(node, TelemetryMetricNames.LEFT_ROWS_WITH_MATCH_ACTUAL));
		double emptyProbeCount = finiteOr(node.getCostFeedbackEmptyRightProbeCountActual(),
				longMetric(node, TelemetryMetricNames.EMPTY_RIGHT_PROBE_COUNT_ACTUAL));
		double maxRightRowsPerLeft = finiteOr(node.getCostFeedbackMaxRightRowsPerLeftActual(),
				longMetric(node, TelemetryMetricNames.MAX_RIGHT_ROWS_PER_LEFT_ACTUAL));
		double leftBranchRows = node instanceof BinaryTupleOperator binary ? actualRows(binary.getLeftArg())
				: Double.NaN;
		double rightBranchRows = node instanceof BinaryTupleOperator binary ? actualRows(binary.getRightArg())
				: Double.NaN;
		double actualWorkRows = aggregate.actualWorkSum().workRows();
		if (!isFiniteNonNegative(actualWorkRows)) {
			double derivedActualWorkRows = actualWorkRows(node, actualRows, leftRows, rightRows, leftBranchRows,
					rightBranchRows);
			actualWorkRows = node instanceof ArbitraryLengthPath || node instanceof ZeroLengthPath
					? maxFinite(derivedActualWorkRows, node.getCostFeedbackActualWorkRows())
					: finiteOr(node.getCostFeedbackActualWorkRows(), derivedActualWorkRows);
		}
		return new OperatorObservation(plannedRows, plannedWorkRows, actualRows, leftRows, rightRows,
				actualWorkRows, leftRowsWithMatch, emptyProbeCount, maxRightRowsPerLeft, leftBranchRows,
				rightBranchRows);
	}

	private double actualWorkRows(TupleExpr node, double actualRows, double leftRows, double rightRows,
			double leftBranchRows, double rightBranchRows) {
		if (node instanceof ArbitraryLengthPath) {
			double pathWork = pathWorkRows(node, actualRows);
			if (isFiniteNonNegative(pathWork)) {
				return pathWork;
			}
		}
		if (node instanceof ZeroLengthPath) {
			double candidates = longMetric(node, ZERO_LENGTH_CANDIDATE_ROWS_ACTUAL);
			if (isFiniteNonNegative(candidates)) {
				return Math.max(actualRows, candidates);
			}
		}
		if (node instanceof Union) {
			double branchRows = sumFiniteRows(leftBranchRows, rightBranchRows);
			if (isFiniteNonNegative(branchRows)) {
				return Math.max(actualRows, branchRows);
			}
		}
		double consumedRows = sumFiniteRows(leftRows, rightRows);
		if (isFiniteNonNegative(consumedRows)) {
			return Math.max(actualRows, consumedRows);
		}
		return actualRows;
	}

	private static double sumFiniteRows(double leftRows, double rightRows) {
		boolean hasLeftRows = isFiniteNonNegative(leftRows);
		boolean hasRightRows = isFiniteNonNegative(rightRows);
		if (!hasLeftRows && !hasRightRows) {
			return Double.NaN;
		}
		return (hasLeftRows ? leftRows : 0.0d) + (hasRightRows ? rightRows : 0.0d);
	}

	private static long saturatingAdd(long left, long right) {
		if (right > 0L && left > Long.MAX_VALUE - right) {
			return Long.MAX_VALUE;
		}
		return left + right;
	}

	private double leftRows(TupleExpr node) {
		double rows = longMetric(node, TelemetryMetricNames.LEFT_ROWS_PROBED_ACTUAL);
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		rows = node.getJoinLeftBindingsConsumedActual();
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		rows = longMetric(node, TelemetryMetricNames.LEFT_ROWS_CONSUMED_ACTUAL);
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		if (node instanceof BinaryTupleOperator binary) {
			return actualRows(binary.getLeftArg());
		}
		return Double.NaN;
	}

	private double rightRows(TupleExpr node) {
		double rows = longMetric(node, TelemetryMetricNames.RIGHT_ROWS_SCANNED_ACTUAL);
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		rows = node.getJoinRightBindingsConsumedActual();
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		rows = longMetric(node, TelemetryMetricNames.RIGHT_ROWS_CONSUMED_ACTUAL);
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		if (node instanceof BinaryTupleOperator binary) {
			return actualRows(binary.getRightArg());
		}
		return Double.NaN;
	}

	private static double actualRows(TupleExpr node) {
		if (node == null) {
			return Double.NaN;
		}
		double rows = node.getCostFeedbackActualRows();
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		rows = node.getResultSizeActual();
		if (isFiniteNonNegative(rows)) {
			return rows;
		}
		return longMetric(node, TelemetryMetricNames.OUTPUT_ROWS_ACTUAL);
	}

	static boolean supportsOperatorFeedback(TupleExpr node) {
		return operatorLearningPolicy(node).recordsDirectEvidence();
	}

	public boolean shouldTrackRuntimeFeedback(TupleExpr tupleExpr) {
		return runtimeFeedbackTrackingEnabled()
				&& adaptiveEvidenceAllowed() && rollout().observationEnabled()
				&& operatorLearningPolicy(tupleExpr).runtimeObservable();
	}

	public boolean shouldRecordDirectEvidence(TupleExpr tupleExpr) {
		return adaptiveEvidenceAllowed() && rollout().observationEnabled() && supportsOperatorFeedback(tupleExpr);
	}

	public boolean shouldExposePlanningEvidence(TupleExpr tupleExpr) {
		return adaptiveEvidenceAllowed() && rollout().cardinalityCorrectionEnabled()
				&& supportsOperatorFeedback(tupleExpr);
	}

	boolean shouldExposeMultiplierPlanningEvidence(TupleExpr tupleExpr) {
		return adaptiveEvidenceAllowed() && rollout().cardinalityCorrectionEnabled()
				&& operatorLearningPolicy(tupleExpr) == LeoOperatorLearningPolicy.LEARN_AS_CHILD_MULTIPLIER;
	}

	private static LeoRolloutProfile rollout() {
		return LeoRolloutProfile.fromSystemProperties();
	}

	private static boolean runtimeFeedbackTrackingEnabled() {
		return propertyEnabled(LmdbEvaluationStatistics.OPERATOR_FEEDBACK_TRACKING_PROPERTY)
				&& propertyEnabled(LmdbEvaluationStatistics.OPERATOR_FEEDBACK_DETAILED_RUNTIME_PROPERTY);
	}

	private static boolean propertyEnabled(String property) {
		String configured = System.getProperty(property);
		return configured == null || Boolean.parseBoolean(configured);
	}

	static LeoOperatorLearningPolicy operatorLearningPolicy(TupleExpr node) {
		if (node instanceof Join
				|| node instanceof LeftJoin
				|| node instanceof Union
				|| node instanceof Difference
				|| node instanceof Intersection
				|| node instanceof ArbitraryLengthPath
				|| node instanceof ZeroLengthPath) {
			return LeoOperatorLearningPolicy.LEARN_DIRECTLY;
		}
		if (node instanceof Filter
				|| node instanceof Projection
				|| node instanceof MultiProjection
				|| node instanceof Extension
				|| node instanceof Distinct
				|| node instanceof Reduced
				|| node instanceof Order
				|| node instanceof QueryRoot) {
			return LeoOperatorLearningPolicy.LEARN_AS_CHILD_MULTIPLIER;
		}
		if (node instanceof StatementPattern
				|| node instanceof BindingSetAssignment
				|| node instanceof Group
				|| node instanceof SingletonSet) {
			return LeoOperatorLearningPolicy.SHADOW_ONLY;
		}
		if (node instanceof Slice || node instanceof Service) {
			return LeoOperatorLearningPolicy.DO_NOT_LEARN;
		}
		return LeoOperatorLearningPolicy.DO_NOT_LEARN;
	}

	private static boolean isSupportedOperator(TupleExpr node) {
		return supportsOperatorFeedback(node);
	}

	private static boolean isRuntimeObservableOperator(TupleExpr node) {
		return operatorLearningPolicy(node).runtimeObservable();
	}

	private static String feedbackPoisonReason(TupleExpr node) {
		if (node == null) {
			return "null-node";
		}
		if (containsSlice(node)) {
			return "slice-capped";
		}
		String plannedSource = node.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE);
		if (plannedSource != null && plannedSource.toLowerCase(java.util.Locale.ROOT).contains("service")) {
			return "remote-service";
		}
		// Written by ResultSizeCountingIterator when hasNext()/next()/close throws (timeout, cancel, error).
		if (node.getLongMetricActual(TelemetryMetricNames.CANCELLED_COUNT_ACTUAL) > 0L
				|| node.getLongMetricActual(TelemetryMetricNames.ABORTED_COUNT_ACTUAL) > 0L) {
			return "aborted-or-rolled-back";
		}
		if (node instanceof Service) {
			return "remote-service";
		}
		long hasNextCalls = node.getHasNextCallCountActual();
		long hasNextTrueCalls = node.getHasNextTrueCountActual();
		if (hasNextCalls >= 0L && hasNextTrueCalls >= 0L && hasNextCalls < hasNextTrueCalls) {
			return "partial-iteration";
		}
		return "";
	}

	private static boolean isCompleted(TupleExpr node) {
		if (node == null) {
			return false;
		}
		if (node.isCostFeedbackCompletedActual() && isFiniteNonNegative(actualRows(node))) {
			double plannedOperatorRepeatedInvocations = node
					.getDoubleMetricPlanned(PLANNED_OPERATOR_REPEATED_INVOCATIONS);
			boolean invocationsCovered = !isFiniteNonNegative(plannedOperatorRepeatedInvocations)
					|| plannedOperatorRepeatedInvocations <= 1.0d
					|| node.getCostFeedbackCloseCountActual() >= Math.max(1L,
							Math.round(plannedOperatorRepeatedInvocations));
			return invocationsCovered && everyCloseExhausted(node, node.getCostFeedbackCloseCountActual());
		}
		long closeCount = node.getLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL);
		if (closeCount <= 0L) {
			return false;
		}
		double plannedOperatorRepeatedInvocations = node.getDoubleMetricPlanned(PLANNED_OPERATOR_REPEATED_INVOCATIONS);
		if (isFiniteNonNegative(plannedOperatorRepeatedInvocations) && plannedOperatorRepeatedInvocations > 1.0d
				&& closeCount < Math.max(1L, Math.round(plannedOperatorRepeatedInvocations))) {
			return false;
		}
		long hasNextCalls = node.getHasNextCallCountActual();
		long hasNextTrueCalls = node.getHasNextTrueCountActual();
		return hasNextCalls >= 0L && hasNextTrueCalls >= 0L && hasNextCalls > hasNextTrueCalls
				&& everyCloseExhausted(node, closeCount);
	}

	/*
	 * Cumulative counters cannot vouch for individual invocations: one exhausted close among N truncated ones still
	 * leaves hasNextCalls > hasNextTrueCalls for the whole history. Close-path completeness therefore requires every
	 * recorded close to have observed a terminal hasNext()==false. Absent metric (-1) means the counters come from a
	 * writer that predates the marker (or a synthetic tree) — fall back to the older, lenient rules. Deliberately NOT
	 * enforced in isObservedInCompletedRoot: the completed-tree rescue exists to accept final cumulative totals for
	 * nodes without terminal-false closes.
	 */
	private static boolean everyCloseExhausted(TupleExpr node, long closeCount) {
		if (!exhaustedCloseInvariantEnabled() || closeCount <= 0L) {
			return true;
		}
		long exhaustedCloses = node.getLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL);
		return exhaustedCloses < 0L || exhaustedCloses >= closeCount;
	}

	private static boolean isObservedInCompletedRoot(TupleExpr node) {
		if (isCompleted(node)) {
			return true;
		}

		if (!isFiniteNonNegative(actualRows(node))) {
			return false;
		}
		long hasNextCalls = node.getHasNextCallCountActual();
		long hasNextTrueCalls = node.getHasNextTrueCountActual();
		if (hasNextCalls >= 0L && hasNextTrueCalls >= 0L && hasNextCalls < hasNextTrueCalls) {
			return false;
		}
		// Rows signaled but never consumed (hasNext true, next never called) mark a short-circuiting consumer:
		// its cumulative actual is a truncation artifact, not a final total.
		long nextCalls = node.getNextCallCountActual();
		if (shortCircuitGuardEnabled() && nextCalls >= 0L && hasNextTrueCalls >= 0L
				&& hasNextTrueCalls > nextCalls) {
			return false;
		}
		long closeCount = node.getLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL);
		double plannedRepeatedInvocations = node.getDoubleMetricPlanned(PLANNED_REPEATED_INVOCATIONS);
		return !isFiniteNonNegative(plannedRepeatedInvocations)
				|| plannedRepeatedInvocations <= 1.0d
				|| closeCount <= 0L
				|| closeCount >= Math.max(1L, Math.round(plannedRepeatedInvocations));
	}

	private static double pathWorkRows(TupleExpr node, double actualRows) {
		return maxFinite(actualRows,
				longMetric(node, PATH_CANDIDATE_ROWS_ACTUAL),
				longMetric(node, PATH_QUEUE_ENQUEUE_ROWS_ACTUAL),
				longMetric(node, PATH_EXPANSION_ITERATIONS_ACTUAL),
				longMetric(node, PATH_RETURNED_ROWS_ACTUAL));
	}

	private static String poisonedObservationReason(TupleExpr node, boolean completedRoot) {
		if (node == null) {
			return "null-node";
		}
		if (completedRoot && containsSlice(node)) {
			return "slice-or-limit-in-subtree";
		}
		if (hasSliceAncestor(node)) {
			return "slice-or-limit-ancestor";
		}
		if (longMetric(node, TelemetryMetricNames.REMOTE_TIMEOUT_COUNT_ACTUAL) > 0.0d
				|| longMetric(node, TelemetryMetricNames.REMOTE_ERROR_COUNT_ACTUAL) > 0.0d
				|| longMetric(node, TelemetryMetricNames.EXPR_ERROR_COUNT_ACTUAL) > 0.0d
				|| longMetric(node, TelemetryMetricNames.CANCELLED_COUNT_ACTUAL) > 0.0d
				|| longMetric(node, TelemetryMetricNames.ABORTED_COUNT_ACTUAL) > 0.0d
				|| longMetric(node, "timeoutActual") > 0.0d
				|| longMetric(node, "cancelledActual") > 0.0d
				|| longMetric(node, "abortedActual") > 0.0d
				|| longMetric(node, "rollbackActual") > 0.0d
				|| longMetric(node, "optimizer.feedbackPoisonedActual") > 0.0d) {
			return "error-timeout-cancel-or-rollback";
		}
		// An abort anywhere above this operator truncates its ancestors' consumption of it, and the throw
		// itself unwinds through every enclosing iterator — cumulative actuals on the whole path are suspect.
		if (abortPoisoningEnabled() && hasAbortedAncestor(node)) {
			return "aborted-ancestor";
		}
		// Legacy operator keys carry no dataset identity; evidence from FROM/FROM NAMED-restricted queries
		// would calibrate unrestricted queries over different data.
		if (legacyDatasetGatingEnabled() && hasDatasetRestrictedSelfOrAncestor(node)) {
			return "dataset-restricted";
		}
		if (longMetric(node, TelemetryMetricNames.ROWS_DROPPED_BY_LIMIT_ACTUAL) > 0.0d
				|| longMetric(node, TelemetryMetricNames.ROWS_SKIPPED_BY_OFFSET_ACTUAL) > 0.0d) {
			return "partial-slice-output";
		}
		long hasNextCalls = node.getHasNextCallCountActual();
		long hasNextTrueCalls = node.getHasNextTrueCountActual();
		if (!completedRoot && !node.isCostFeedbackCompletedActual() && hasNextCalls >= 0L && hasNextTrueCalls >= 0L
				&& hasNextCalls == hasNextTrueCalls && hasNextTrueCalls > 0L) {
			return "no-terminal-false-outside-completed-root";
		}
		return "";
	}

	private static boolean hasSliceAncestor(QueryModelNode node) {
		QueryModelNode current = node == null ? null : node.getParentNode();
		while (current != null) {
			if (current instanceof Slice) {
				return true;
			}
			current = current.getParentNode();
		}
		return false;
	}

	private static boolean hasAbortedAncestor(QueryModelNode node) {
		QueryModelNode current = node == null ? null : node.getParentNode();
		while (current != null) {
			if (isAbortMarked(current)) {
				return true;
			}
			current = current.getParentNode();
		}
		return false;
	}

	private static boolean isAbortMarked(QueryModelNode node) {
		return node.getLongMetricActual(TelemetryMetricNames.CANCELLED_COUNT_ACTUAL) > 0L
				|| node.getLongMetricActual(TelemetryMetricNames.ABORTED_COUNT_ACTUAL) > 0L;
	}

	private static boolean containsSlice(TupleExpr node) {
		if (node instanceof Slice) {
			return true;
		}
		if (node instanceof UnaryTupleOperator unary) {
			return containsSlice(unary.getArg());
		}
		if (node instanceof BinaryTupleOperator binary) {
			return containsSlice(binary.getLeftArg()) || containsSlice(binary.getRightArg());
		}
		return false;
	}

	private void evictOldestIfNeeded() {
		evictOldestIfNeeded(learnedByOperator);
	}

	private void evictOldestIfNeeded(Map<?, ?> map) {
		while (map.size() > MAX_ENTRIES) {
			var iterator = map.keySet().iterator();
			if (!iterator.hasNext()) {
				return;
			}
			iterator.next();
			iterator.remove();
		}
	}

	private List<OperatorKey> keysForRecord(TupleExpr node, String executionMode) {
		List<OperatorKey> keys = new ArrayList<>(4);
		String planningContext = recordContextTag(node);
		addRecordKeys(keys, node, executionMode, planningContext);
		if (!planningContext.isBlank()) {
			addRecordKeys(keys, node, executionMode, "");
		}
		return keys.isEmpty() ? List.of() : List.copyOf(keys);
	}

	private void addRecordKeys(List<OperatorKey> keys, TupleExpr node, String executionMode, String planningContext) {
		OperatorKey exact = keyFor(node, executionMode, planningContext, LeoOperatorKey.ConstantMode.EXACT, false,
				null);
		OperatorKey generalized = keyFor(node, executionMode, planningContext,
				LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT, true,
				exact == null ? null : exact.fingerprint());
		addIfDistinct(keys, exact);
		addIfDistinct(keys, generalized);
	}

	private List<OperatorKey> keysForEstimate(TupleExpr node, String executionMode) {
		return keysForEstimate(node, executionMode, null);
	}

	private List<OperatorKey> keysForEstimate(TupleExpr node, String executionMode, String planningContext) {
		List<OperatorKey> keys = new ArrayList<>(6);
		String normalizedContext = normalize(planningContext);
		addEstimateKeys(keys, node, executionMode, normalizedContext);
		if (!normalizedContext.isBlank()) {
			addEstimateKeys(keys, node, executionMode, "");
		}
		return keys.isEmpty() ? List.of() : List.copyOf(keys);
	}

	private void addEstimateKeys(List<OperatorKey> keys, TupleExpr node, String executionMode, String planningContext) {
		OperatorKey exact = keyFor(node, executionMode, planningContext, LeoOperatorKey.ConstantMode.EXACT, false,
				null);
		OperatorKey legacy = legacyKeyFor(node, executionMode);
		OperatorKey generalized = keyFor(node, executionMode, planningContext,
				LeoOperatorKey.ConstantMode.PREDICATE_AND_CONTEXT_EXACT, true,
				exact == null ? null : exact.fingerprint());
		addIfDistinct(keys, exact);
		addIfDistinct(keys, legacy);
		addIfDistinct(keys, generalized);
	}

	private static void addIfDistinct(List<OperatorKey> keys, OperatorKey key) {
		if (key != null && !keys.contains(key)) {
			keys.add(key);
		}
	}

	private OperatorKey keyFor(TupleExpr node, String executionMode, String planningContext,
			LeoOperatorKey.ConstantMode constantMode, boolean generalized, String abstractedSignature) {
		if (node == null || !isSupportedOperator(node)) {
			return null;
		}
		String effectiveExecutionMode = physicalExecutionMode(node, executionMode);
		LeoOperatorKey leoKey = LeoOperatorKey.from(node, effectiveExecutionMode, constantMode);
		String specificity = generalized ? "predicate-context" : "exact";
		return new OperatorKey("leo:" + specificity + ':' + leoKey.operatorType(),
				leoKey.structuralFingerprint(), "", "",
				"mode=" + leoKey.executionMode() + contextSuffix(planningContext),
				displayBindings(node), abstractedSignature == null ? "" : abstractedSignature);
	}

	private OperatorKey legacyKeyFor(TupleExpr node, String executionMode) {
		if (node == null || !isSupportedOperator(node)) {
			return null;
		}
		if (executionMode == null) {
			OperatorKey cached = nullModeKeyCache.get(node);
			if (cached != null) {
				return cached;
			}
		}
		String effectiveExecutionMode = node instanceof ArbitraryLengthPath || node instanceof ZeroLengthPath
				? pathEndpointMode(node, executionMode)
				: executionMode;
		LeoOperatorKey leoKey = LeoOperatorKey.from(node, effectiveExecutionMode);
		OperatorKey key = new OperatorKey("leo:" + leoKey.operatorType(), leoKey.structuralFingerprint(), "", "",
				"mode=" + leoKey.executionMode(), displayBindings(node), "");
		if (executionMode == null) {
			if (nullModeKeyCache.size() > KEY_CACHE_MAX_SIZE) {
				nullModeKeyCache.clear();
			}
			nullModeKeyCache.put(node, key);
		}
		return key;
	}

	private String displayBindings(TupleExpr node) {
		if (node instanceof BinaryTupleOperator binary) {
			Set<String> leftBindings = plannerBindingNames(binary.getLeftArg().getBindingNames());
			Set<String> rightBindings = plannerBindingNames(binary.getRightArg().getBindingNames());
			Set<String> sharedBindings = new HashSet<>(leftBindings);
			sharedBindings.retainAll(rightBindings);
			return "leftBindings=" + sortedBindings(leftBindings)
					+ ", rightBindings=" + sortedBindings(rightBindings)
					+ ", sharedBindings=" + sortedBindings(sharedBindings);
		}
		if (node instanceof ArbitraryLengthPath || node instanceof ZeroLengthPath) {
			return "outputBindings=" + sortedBindings(plannerBindingNames(node.getBindingNames()));
		}
		return "";
	}

	private String pathEndpointMode(TupleExpr node, String executionMode) {
		String mode = normalizePathEndpointMode(executionMode);
		if (mode != null) {
			return mode;
		}
		mode = normalizePathEndpointMode(node.getStringMetricPlanned(PLANNED_PROPERTY_PATH_ENDPOINT_MODE));
		if (mode != null) {
			return mode;
		}
		mode = normalizePathEndpointMode(node.getStringMetricPlanned(OPTIMIZER_PATH_ENDPOINT_MODE));
		if (mode != null) {
			return mode;
		}
		mode = constantEndpointMode(node);
		return mode == null ? PATH_MODE_UNKNOWN : mode;
	}

	private String physicalExecutionMode(TupleExpr node, String executionMode) {
		if (node instanceof ArbitraryLengthPath || node instanceof ZeroLengthPath) {
			return pathEndpointMode(node, executionMode);
		}
		String explicit = firstNonBlank(executionMode,
				node == null ? null : node.getStringMetricPlanned(PLANNED_PHYSICAL_IMPLEMENTATION),
				node == null ? null : node.getStringMetricPlanned(LEO_PHYSICAL_IMPLEMENTATION),
				node == null ? null : node.getStringMetricPlanned(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE),
				node == null ? null : node.getStringMetricPlanned("plannedEstimateFusion"));
		if (explicit != null) {
			return explicit;
		}
		if ((node instanceof Join || node instanceof LeftJoin)
				&& isFiniteNonNegative(node.getDoubleMetricPlanned(PLANNED_REPEATED_INVOCATIONS))
				&& node.getDoubleMetricPlanned(PLANNED_REPEATED_INVOCATIONS) > 1.0d) {
			return "bound-lookup";
		}
		return "logical";
	}

	private static String firstNonBlank(String... values) {
		if (values == null) {
			return null;
		}
		for (String value : values) {
			String normalized = normalize(value);
			if (!normalized.isBlank()) {
				return normalized;
			}
		}
		return null;
	}

	private static String recordContextTag(TupleExpr node) {
		return normalize(node == null ? null : node.getStringMetricPlanned(LEO_BINDING_SHAPE_KEY));
	}

	private static String contextSuffix(String planningContext) {
		String normalized = normalize(planningContext);
		return normalized.isBlank() ? "" : "|bindingShape=" + normalized;
	}

	private static String bindingShapeContext(BindingUniverse universe, BindingShape bindingShape,
			TupleExpr tupleExpr) {
		BindingShape shape = bindingShape == null ? BindingShape.from(tupleExpr, universe) : bindingShape;
		if (shape == null || shape.equals(BindingShape.empty())) {
			return "";
		}
		return "possible=" + shape.possible()
				+ ";assured=" + shape.assured()
				+ ";nullable=" + shape.nullable()
				+ ";local=" + shape.localBindOutputs();
	}

	private static String normalize(String value) {
		return value == null ? "" : value.trim();
	}

	private String constantEndpointMode(TupleExpr node) {
		Var subjectVar = null;
		Var objectVar = null;
		if (node instanceof ArbitraryLengthPath path) {
			subjectVar = path.getSubjectVar();
			objectVar = path.getObjectVar();
		} else if (node instanceof ZeroLengthPath path) {
			subjectVar = path.getSubjectVar();
			objectVar = path.getObjectVar();
		}
		boolean subjectBound = subjectVar != null && subjectVar.hasValue();
		boolean objectBound = objectVar != null && objectVar.hasValue();
		if (subjectBound && objectBound) {
			return PATH_MODE_BETWEEN;
		}
		if (subjectBound) {
			return PATH_MODE_FROM_START;
		}
		if (objectBound) {
			return PATH_MODE_TO_END;
		}
		return null;
	}

	private static String normalizePathEndpointMode(String mode) {
		if (mode == null || mode.isBlank()) {
			return null;
		}
		String normalized = mode.trim();
		String normalizedLower = normalized.toLowerCase(java.util.Locale.ROOT);
		if (PATH_MODE_FULL_SCAN.equals(normalized) || "unbound".equals(normalizedLower)) {
			return PATH_MODE_FULL_SCAN;
		}
		if (PATH_MODE_FROM_START.equals(normalized) || "start".equals(normalizedLower)
				|| "subject".equals(normalizedLower) || normalizedLower.contains("bound-subject")) {
			return PATH_MODE_FROM_START;
		}
		if (PATH_MODE_TO_END.equals(normalized) || "end".equals(normalizedLower)
				|| "object".equals(normalizedLower) || normalizedLower.contains("bound-object")) {
			return PATH_MODE_TO_END;
		}
		if (PATH_MODE_BETWEEN.equals(normalized) || "both".equals(normalizedLower)
				|| normalizedLower.contains("bound-pair") || normalizedLower.contains("both-endpoints")) {
			return PATH_MODE_BETWEEN;
		}
		return normalized;
	}

	private static Set<String> plannerBindingNames(Set<String> bindingNames) {
		if (bindingNames == null || bindingNames.isEmpty()) {
			return Set.of();
		}
		Set<String> plannerNames = new HashSet<>();
		for (String bindingName : bindingNames) {
			if (bindingName != null && !bindingName.startsWith("_const_")) {
				plannerNames.add(bindingName);
			}
		}
		return plannerNames;
	}

	private static String sortedBindings(Set<String> bindingNames) {
		if (bindingNames == null || bindingNames.isEmpty()) {
			return "";
		}
		List<String> sorted = new ArrayList<>(bindingNames);
		Collections.sort(sorted);
		return String.join(",", sorted);
	}

	private static void readMultiplierEntries(DataInputStream in, Map<OperatorKey, LearnedMultiplierCounts> target)
			throws IOException {
		int entries = in.readInt();
		if (entries < 0 || entries > MAX_ENTRIES * 4) {
			throw new IOException("Invalid multiplier-feedback count: " + entries);
		}
		for (int i = 0; i < entries; i++) {
			OperatorKey key = OperatorKey.readFrom(in);
			LearnedMultiplierCounts counts = LearnedMultiplierCounts.readFrom(in);
			if (counts.sampleCount > 0L) {
				target.put(key, counts);
			}
		}
	}

	private static void importLegacyFrontierPriors(FrontierLearningModel target,
			Map<OperatorKey, LearnedOperatorCounts> operators,
			Map<OperatorKey, LearnedMultiplierCounts> multipliers) {
		for (Map.Entry<OperatorKey, LearnedOperatorCounts> entry : operators.entrySet()) {
			LearnedOperatorCounts counts = entry.getValue();
			String family = legacyOperatorFamily(entry.getKey().operatorType());
			target.importLegacyFamilyPrior(family, FrontierCostDimension.OUTPUT_ROWS, counts.plannedRowsSum,
					counts.actualRowsSum, counts.sampleCount);
			target.importLegacyFamilyPrior(family, FrontierCostDimension.SOURCE_ROWS_SCANNED,
					counts.plannedWorkRowsSum, counts.actualWorkRowsSum, counts.sampleCount);
		}
		for (Map.Entry<OperatorKey, LearnedMultiplierCounts> entry : multipliers.entrySet()) {
			LearnedMultiplierCounts counts = entry.getValue();
			String family = legacyOperatorFamily(entry.getKey().operatorType());
			target.importLegacyFamilyPrior(family, FrontierCostDimension.OUTPUT_ROWS, counts.plannedRowsSum,
					counts.actualRowsSum, counts.sampleCount);
			double workRatio = counts.confidenceModel.workCorrectionRatio();
			double plannedWork = workRatio > 0.0d && Double.isFinite(workRatio)
					? counts.actualWorkRowsSum / workRatio
					: Double.NaN;
			target.importLegacyFamilyPrior(family, FrontierCostDimension.SOURCE_ROWS_SCANNED, plannedWork,
					counts.actualWorkRowsSum, counts.sampleCount);
		}
	}

	private static String legacyOperatorFamily(String operatorType) {
		if (operatorType == null || operatorType.isBlank()) {
			return "unknown";
		}
		int separator = operatorType.lastIndexOf(':');
		String family = separator < 0 ? operatorType : operatorType.substring(separator + 1);
		return family.isBlank() ? "unknown" : family.toLowerCase(java.util.Locale.ROOT);
	}

	private static void readShadowEntries(DataInputStream in, Map<OperatorKey, ShadowOperatorCounts> target)
			throws IOException {
		int entries = in.readInt();
		if (entries < 0 || entries > MAX_ENTRIES * 4) {
			throw new IOException("Invalid shadow-feedback count: " + entries);
		}
		for (int i = 0; i < entries; i++) {
			OperatorKey key = OperatorKey.readFrom(in);
			ShadowOperatorCounts counts = ShadowOperatorCounts.readFrom(in);
			if (counts.hasEvidence()) {
				target.put(key, counts);
			}
		}
	}

	private static void readPlanCandidateEntries(DataInputStream in, Map<OperatorKey, PlanCandidateCounts> target)
			throws IOException {
		int entries = in.readInt();
		if (entries < 0 || entries > MAX_ENTRIES * 4) {
			throw new IOException("Invalid plan-candidate-feedback count: " + entries);
		}
		for (int i = 0; i < entries; i++) {
			OperatorKey key = OperatorKey.readFrom(in);
			PlanCandidateCounts counts = PlanCandidateCounts.readFrom(in);
			if (counts.hasEvidence()) {
				target.put(key, counts);
			}
		}
	}

	private static void readSemiAntiEntries(DataInputStream in, Map<SemiAntiSurfaceKey, SemiAntiCounts> target,
			int version)
			throws IOException {
		int entries = in.readInt();
		if (entries < 0 || entries > MAX_ENTRIES * 4) {
			throw new IOException("Invalid semi/anti-feedback count: " + entries);
		}
		for (int i = 0; i < entries; i++) {
			SemiAntiSurfaceKey key = SemiAntiSurfaceKey.readFrom(in);
			SemiAntiCounts counts = SemiAntiCounts.readFrom(in, version);
			if (counts.observationCount > 0L) {
				target.put(key, counts);
			}
		}
	}

	private static void readTypedSemiAntiDistinctEntries(DataInputStream in,
			Map<TypedSemiAntiDistinctKey, TypedSemiAntiDistinctCounts> target) throws IOException {
		int entries = in.readInt();
		if (entries < 0 || entries > MAX_ENTRIES * 4) {
			throw new IOException("Invalid typed semi/anti distinct-feedback count: " + entries);
		}
		for (int index = 0; index < entries; index++) {
			TypedSemiAntiDistinctKey key = TypedSemiAntiDistinctKey.readFrom(in);
			TypedSemiAntiDistinctCounts counts = TypedSemiAntiDistinctCounts.readFrom(in);
			if (counts.observationCount() > 0L) {
				target.put(key, counts);
			}
		}
	}

