	private static double longMetric(QueryModelNode node, String metricName) {
		return node == null ? Double.NaN : node.getLongMetricActual(metricName);
	}

	private static double maxFinite(double... values) {
		double max = Double.NaN;
		for (double value : values) {
			if (isFiniteNonNegative(value)) {
				max = Double.isNaN(max) ? value : Math.max(max, value);
			}
		}
		return max;
	}

	private static double finiteOr(double preferred, double fallback) {
		return isFiniteNonNegative(preferred) ? preferred : fallback;
	}

	private static boolean isFiniteNonNegative(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	private static double clampCorrection(double ratio, long sampleCount) {
		if (!Double.isFinite(ratio) || ratio <= 0.0d) {
			return Double.NaN;
		}
		if (legacyEvidenceScaledClampEnabled()) {
			// Evidence-scaled FLOOR only (4x down per observation): downward crushes flip plans toward risky
			// alternatives — the static 1e-4 floor let a single bad run shrink an estimate 10000x. Upward
			// corrections are conservative and keep the static ceiling; single-sample large upward misses are
			// the signal legacy learning exists to correct.
			double evidenceFactor = Math.pow(4.0d, Math.min(Math.max(1L, sampleCount), 8L));
			double lower = Math.max(MIN_CORRECTION_RATIO, 1.0d / evidenceFactor);
			return Math.max(lower, Math.min(MAX_CORRECTION_RATIO, ratio));
		}
		return Math.max(MIN_CORRECTION_RATIO, Math.min(MAX_CORRECTION_RATIO, ratio));
	}

	private static double qError(double actualRows, double estimatedRows) {
		if (!isFiniteNonNegative(actualRows) || !isFiniteNonNegative(estimatedRows)) {
			return Double.NaN;
		}
		if (actualRows == 0.0d && estimatedRows == 0.0d) {
			return 1.0d;
		}
		if (actualRows == 0.0d || estimatedRows == 0.0d) {
			return MAX_CORRECTION_RATIO;
		}
		double ratio = Math.max(actualRows / estimatedRows, estimatedRows / actualRows);
		return Double.isFinite(ratio) ? Math.max(1.0d, Math.min(MAX_CORRECTION_RATIO, ratio)) : Double.NaN;
	}

	private static double clampRowsByBase(double rows, double baseRows) {
		if (!isFiniteNonNegative(rows)) {
			return Double.NaN;
		}
		if (!isFiniteNonNegative(baseRows) || baseRows == 0.0d) {
			return rows;
		}
		return Math.max(baseRows * MIN_CORRECTION_RATIO, Math.min(baseRows * MAX_CORRECTION_RATIO, rows));
	}

	private static double blend(double baseRows, double learnedRows, double confidence) {
		if (!isFiniteNonNegative(learnedRows)) {
			return baseRows;
		}
		if (!isFiniteNonNegative(baseRows) || baseRows == 0.0d) {
			return learnedRows;
		}
		if (learnedRows == 0.0d) {
			return baseRows * Math.max(0.0d, 1.0d - confidence);
		}
		double boundedLearnedRows = clampRowsByBase(learnedRows, baseRows);
		return (baseRows * Math.max(0.0d, 1.0d - confidence)) + (boundedLearnedRows * confidence);
	}

	private static double confidence(long sampleCount) {
		if (sampleCount <= 0L) {
			return 0.0d;
		}
		return Math.min(0.90d, 0.35d + Math.max(0L, sampleCount - 1L) * 0.075d);
	}

	private static int intProperty(String property, int defaultValue) {
		try {
			return Integer.getInteger(property, defaultValue);
		} catch (RuntimeException e) {
			return defaultValue;
		}
	}

	private static long longProperty(String property, long defaultValue) {
		try {
			String value = System.getProperty(property);
			return value == null || value.isBlank() ? defaultValue : Long.parseLong(value.trim());
		} catch (RuntimeException e) {
			return defaultValue;
		}
	}

	private static double doubleProperty(String property, double defaultValue) {
		try {
			String value = System.getProperty(property);
			return value == null || value.isBlank() ? defaultValue : Double.parseDouble(value.trim());
		} catch (RuntimeException e) {
			return defaultValue;
		}
	}

	private static void writeString(DataOutputStream out, String value) throws IOException {
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		out.writeInt(bytes.length);
		out.write(bytes);
	}

	private static String readString(DataInputStream in) throws IOException {
		int length = in.readInt();
		if (length < 0 || length > 1_000_000) {
			throw new IOException("Invalid string length: " + length);
		}
		byte[] bytes = new byte[length];
		in.readFully(bytes);
		return new String(bytes, StandardCharsets.UTF_8);
	}

	record OperatorEstimate(double rows, double workRows, String source, long evidenceCount, double confidence,
			double correctionConfidence, String feedbackKey, double rowQErrorMean, double rowQErrorMax,
			double workQErrorMean, double workQErrorMax, double uncertaintyRows) {
	}

	record SemiAntiEstimate(long observationCount, long outerRows, long matchedRows, long unmatchedRows,
			long distinctKeys, long matchedKeys, long unmatchedKeys, long repeatedOuterRows, long rhsRowsExamined,
			long exhaustedFailures, long iteratorOpens, long hashBuildRows, long hashProbeRows, long cacheLookups,
			long strategyChanges, long physicalObservationCount, long rhsSourceRowsScanned) {
	}

	record TypedSemiAntiDistinctEstimate(long exactObservationCount, long approximateObservationCount,
			long distinctPoint, double estimateVariance, double aggregateRelativeError) {
	}

	private record OperatorObservation(double plannedRows, double plannedWorkRows, double actualRows, double leftRows,
			double rightRows, double actualWorkRows, double leftRowsWithMatch, double emptyProbeCount,
			double maxRightRowsPerLeft, double leftBranchRows, double rightBranchRows) {
	}

	private static final class SemiAntiCounts {
		private long observationCount;
		private long outerRows;
		private long matchedRows;
		private long unmatchedRows;
		private long distinctKeys;
		private long matchedKeys;
		private long unmatchedKeys;
		private long repeatedOuterRows;
		private long rhsRowsExamined;
		private long exhaustedFailures;
		private long iteratorOpens;
		private long hashBuildRows;
		private long hashProbeRows;
		private long cacheLookups;
		private long strategyChanges;
		private long physicalObservationCount;
		private long rhsSourceRowsScanned;

		private void add(SemiAntiOutcomeObservation observation, long sourceRowsScanned) {
			observationCount = saturatingAdd(observationCount, 1L);
			outerRows = saturatingAdd(outerRows, observation.outerRows());
			matchedRows = saturatingAdd(matchedRows, observation.matchedRows());
			unmatchedRows = saturatingAdd(unmatchedRows, observation.unmatchedRows());
			distinctKeys = saturatingAdd(distinctKeys, observation.distinctCorrelationKeys());
			matchedKeys = saturatingAdd(matchedKeys, observation.matchedKeys());
			unmatchedKeys = saturatingAdd(unmatchedKeys, observation.unmatchedKeys());
			repeatedOuterRows = saturatingAdd(repeatedOuterRows, observation.repeatedOuterRows());
			rhsRowsExamined = saturatingAdd(rhsRowsExamined, observation.rhsRowsExamined());
			exhaustedFailures = saturatingAdd(exhaustedFailures, observation.exhaustedFailures());
			iteratorOpens = saturatingAdd(iteratorOpens, observation.iteratorOpens());
			hashBuildRows = saturatingAdd(hashBuildRows, observation.hashBuildRows());
			hashProbeRows = saturatingAdd(hashProbeRows, observation.hashProbeRows());
			cacheLookups = saturatingAdd(cacheLookups, observation.cacheLookups());
			if (!observation.strategyChangeReason().isBlank()) {
				strategyChanges = saturatingAdd(strategyChanges, 1L);
			}
			if (sourceRowsScanned >= 0L) {
				physicalObservationCount = saturatingAdd(physicalObservationCount, 1L);
				rhsSourceRowsScanned = saturatingAdd(rhsSourceRowsScanned, sourceRowsScanned);
			}
		}

		private SemiAntiEstimate estimate() {
			return new SemiAntiEstimate(
					observationCount,
					outerRows,
					matchedRows,
					unmatchedRows,
					distinctKeys,
					matchedKeys,
					unmatchedKeys,
					repeatedOuterRows,
					rhsRowsExamined,
					exhaustedFailures,
					iteratorOpens,
					hashBuildRows,
					hashProbeRows,
					cacheLookups,
					strategyChanges,
					physicalObservationCount,
					rhsSourceRowsScanned);
		}

		private void writeTo(DataOutputStream out) throws IOException {
			out.writeLong(observationCount);
			out.writeLong(outerRows);
			out.writeLong(matchedRows);
			out.writeLong(unmatchedRows);
			out.writeLong(distinctKeys);
			out.writeLong(matchedKeys);
			out.writeLong(unmatchedKeys);
			out.writeLong(repeatedOuterRows);
			out.writeLong(rhsRowsExamined);
			out.writeLong(exhaustedFailures);
			out.writeLong(iteratorOpens);
			out.writeLong(hashBuildRows);
			out.writeLong(hashProbeRows);
			out.writeLong(cacheLookups);
			out.writeLong(strategyChanges);
			out.writeLong(physicalObservationCount);
			out.writeLong(rhsSourceRowsScanned);
		}

		private static SemiAntiCounts readFrom(DataInputStream in, int version) throws IOException {
			SemiAntiCounts counts = new SemiAntiCounts();
			counts.observationCount = nonNegative(in.readLong());
			counts.outerRows = nonNegative(in.readLong());
			counts.matchedRows = nonNegative(in.readLong());
			counts.unmatchedRows = nonNegative(in.readLong());
			counts.distinctKeys = nonNegative(in.readLong());
			counts.matchedKeys = nonNegative(in.readLong());
			counts.unmatchedKeys = nonNegative(in.readLong());
			counts.repeatedOuterRows = nonNegative(in.readLong());
			counts.rhsRowsExamined = nonNegative(in.readLong());
			counts.exhaustedFailures = nonNegative(in.readLong());
			counts.iteratorOpens = nonNegative(in.readLong());
			counts.hashBuildRows = nonNegative(in.readLong());
			counts.hashProbeRows = nonNegative(in.readLong());
			counts.cacheLookups = nonNegative(in.readLong());
			counts.strategyChanges = nonNegative(in.readLong());
			if (version >= PHYSICAL_SEMI_ANTI_PERSIST_VERSION) {
				counts.physicalObservationCount = nonNegative(in.readLong());
				counts.rhsSourceRowsScanned = nonNegative(in.readLong());
			}
			return counts;
		}

		private static long nonNegative(long value) throws IOException {
			if (value < 0L) {
				throw new IOException("Negative semi/anti feedback counter");
			}
			return value;
		}
	}

